 function partCount(count:number){if(count<1||count>24)return;edit(s=>{const parts=s.parts.slice(0,count);while(parts.length<count)parts.push(createPart(['soprano','alto','tenor','bass'][parts.length%4]));return {...s,parts,leadId:parts.some(p=>p.id===s.leadId)?s.leadId:parts[0].id};});}
