 async function chatAction(action:'new'|'switch'|'rewind'|'retry',id=''){
  if(viewTimer.current)clearTimeout(viewTimer.current);await flush();const p=projectRef.current!;
  if(action==='new'||action==='switch')await api(`/projects/${p.id}/view`,'PUT',{...p.view,chatId:p.chatId,draft,effort,referenceIds,creationMode,barSelection});
  const result=await api(action==='new'?`/projects/${p.id}/chats`:action==='switch'?`/projects/${p.id}/chats/${id}/activate`:`/projects/${p.id}/chats/rewind/${id}`,'POST',{version:p.version,retry:action==='retry'});
  if(projectRef.current?.id!==p.id)return;
  if(action==='rewind'||action==='retry'){localStorage.removeItem(`choirloom-chat-${user.id}-${p.id}-${p.chatId}`);localStorage.removeItem(`choirloom-draft-${user.id}-${p.id}`);localStorage.removeItem(`choirloom-pending-${user.id}-${p.id}`);}
  await loadProject(p.id);if(result.restored){setEffort(result.restored.effort);setDraft(action==='retry'?'':result.restored.prompt);setReferenceIds(action==='retry'?[]:result.restored.referenceIds);setBarSelection(result.restored.selection||null);setCreationMode(result.restored.mode==='chat'?'arrange':result.restored.mode);if(result.job)setJob(result.job);}else setJob(null);
 }
 async function send(mode:'chat'|'arrange'|'compose'|'revise'){await flush();const p=projectRef.current!;const prompt=draft.trim()||(mode==='compose'?t('依照所選風格與聲部，創作一首有原創旋律與歌詞的新歌。','Compose a new original song with melody and lyrics using the selected styles and voices.'):mode==='revise'?t('改善這首歌的旋律、歌詞與和聲，保留鎖定音符。','Refine this song’s melody, lyrics and harmony while preserving locked notes.'):mode==='arrange'?t('依照我選擇的風格與聲部，完成所有和聲聲部，保留主旋律。','Complete the harmony parts using my selected styles and voices. Preserve the lead melody.'):'');if(!prompt)return;const ids=[...new Set([...referenceIds,...(p.references||[]).filter(f=>prompt.split(/\s+/).includes('@'+f.mention)).map(f=>f.id)])];const body={conversationId:p.chatId,prompt,effort,locale,mode,referenceIds:ids,selection:barSelection||undefined,requestId:crypto.randomUUID()};const key=`choirloom-pending-${user.id}-${p.id}`;try{const previous=JSON.parse(localStorage.getItem(key)||'null');if(previous&&JSON.stringify({...previous,requestId:''})===JSON.stringify({...body,requestId:''}))body.requestId=previous.requestId;}catch{}localStorage.setItem(key,JSON.stringify(body));const r=await api(`/projects/${p.id}/ai`,'POST',body);localStorage.removeItem(key);if(projectRef.current?.id!==p.id)return;setDraft('');setReferenceIds([]);setJob(r);record('info','chat.submitted',{jobId:r.id,projectId:p.id,referenceCount:ids.length});}


 async function renderVocals(){
  const id=projectRef.current?.id;if(!id||renderSubmitting)return;
  const missing=latestScore.current.parts.filter(p=>p.notes.some(n=>n.pitch!==null)&&!p.voicebank);
  if(missing.length){setTab('ensemble');setPartEditor(missing[0].id);setScoreFocus(false);const message=t('請先為以下聲部選擇合成歌手：','Choose a synthetic singer for: ')+missing.map(p=>p.name).join('、');setRenderMessage(message);setNotice(message);record('warn','render.validation.failed',{projectId:id,partIds:missing.map(p=>p.id)});return;}
  setRenderSubmitting(true);setRenderMessage(t('正在儲存樂譜…','Saving score…'));record('info','render.requested',{projectId:id});
  try{await flush();if(projectRef.current?.id!==id)return;setRenderMessage(t('正在提交合成工作…','Submitting render…'));const r=await api(`/projects/${id}/render`,'POST');if(projectRef.current?.id!==id)return;setRenderJob((previous:any)=>previous?.id===r.id?previous:r);setJob((previous:any)=>previous?.id===r.id?previous:r);setRenderMessage('');record('info','render.accepted',{projectId:id,jobId:r.id});}
  catch(e:any){if(projectRef.current?.id===id){setRenderMessage(errorText[e.message]?t(...errorText[e.message]):t('無法確認合成請求是否成功。重新連線後會恢復伺服器狀態。','Could not confirm the render request. Reconnect to recover server status.'));fail(e);}}
  finally{setRenderSubmitting(false);}
 }
